export type AgentState = 'working' | 'done' | 'failed' | 'idle';

export interface FixtureAgent {
  id: string;
  label: string;
  state: AgentState;
  task: string;
  messageCount: number | null;
}

const agents: readonly FixtureAgent[] = [
  {
    id: 'recon',
    label: 'Component recon',
    state: 'working',
    task: 'Map injectable presentation props',
    messageCount: 18
  },
  {
    id: 'timeline',
    label: 'Timeline review',
    state: 'done',
    task: 'Verify measured turn virtualization',
    messageCount: 27
  },
  {
    id: 'qa',
    label: 'Fixture QA',
    state: 'failed',
    task: 'Run the Svelte check again',
    messageCount: 6
  }
];

export function statusLabel(state: AgentState): string {
  if (state === 'working') return 'Working';
  if (state === 'done') return 'Done';
  if (state === 'failed') return 'Failed';
  return 'Idle';
}

export function activeAgents(
  rows: readonly FixtureAgent[]
): readonly FixtureAgent[] {
  return rows.filter((row) => row.state === 'working');
}

export function agentsByState(
  rows: readonly FixtureAgent[]
): ReadonlyMap<AgentState, readonly FixtureAgent[]> {
  const states: AgentState[] = ['working', 'done', 'failed', 'idle'];
  return new Map(
    states.map((state) => [
      state,
      rows.filter((row) => row.state === state)
    ])
  );
}

export const fixtureSummary = {
  total: agents.length,
  active: activeAgents(agents).length,
  labels: agents.map((agent) => statusLabel(agent.state))
};
